// Merges the form submission with any existing row for this contact (matched by name).
// New contacts get sensible defaults; existing contacts keep their prior values unless overridden.
const form = $('Log Interaction Form').first().json;
const existingRows = $input.all().map(i => i.json);
const formName = (form['Contact Name'] || '').trim();
const match = existingRows.find(r => (r.name || '').trim().toLowerCase() === formName.toLowerCase());

const today = new Date().toISOString().split('T')[0];
const newNote = form['Discussion Notes'] ? `[${today}] ${form['Discussion Notes']}` : '';

const merged = {
  name: formName,
  phone: form['Phone (e.g. +2348012345678)'] || (match ? match.phone : ''),
  email: form['Email'] || (match ? match.email : ''),
  birthday: form['Birthday (YYYY-MM-DD)'] || (match ? match.birthday : ''),
  education: form['Education'] || (match ? match.education : ''),
  work: form['Work / Position'] || (match ? match.work : ''),
  relationship_category: form['Relationship Category'] || (match ? match.relationship_category : 'New Contact'),
  priority: form['Priority'] || (match ? match.priority : 'Medium'),
  busy_level: form['Busy Level'] || (match ? match.busy_level : 'Moderate'),
  relationship_goal: form['Relationship Goal'] || (match ? match.relationship_goal : ''),
  notes: match && match.notes ? `${newNote}\n${match.notes}`.trim() : newNote,
  last_contacted_date: today,
  birthday_synced: match ? (match.birthday_synced || 'false') : 'false',
  status: match ? (match.status || 'Active') : 'Active'
};

return [{ json: merged }];

// Same cadence/relationship-plan logic as CM-01 — keep the two in sync if you tune the rules.
const BASE_DAYS = { High: 30, Medium: 60, Low: 120 };
const BUSY_MULTIPLIER = { 'Very Busy': 1.5, 'Moderate': 1, 'Flexible': 0.75 };
const APPROACH_NOTES = {
  'New Contact': 'Reference how you met and something specific you discussed. Aim to convert this into a call or coffee within 30 days.',
  'Close Friend': 'Casual, frequent check-ins are fine — suggest meeting in person when you can.',
  'Family': 'Keep it personal and warm. Prioritize presence over frequency.',
  'Professional': 'Lead with a genuine update, ask about their work, and add value (an article, an intro, an opportunity) before asking for anything.',
  'Mentor': 'Come with a specific question or an update on advice they gave you. Respect their time — be concise.',
  'Acquaintance': 'Low-pressure, occasional check-ins. A birthday message or a relevant share is enough to stay on their radar.'
};

function addDays(dateStr, days) {
  const d = dateStr ? new Date(dateStr) : new Date();
  if (isNaN(d.getTime())) d.setTime(Date.now());
  d.setDate(d.getDate() + days);
  return d.toISOString().split('T')[0];
}

function roundToWeek(days) {
  return Math.max(7, Math.round(days / 7) * 7);
}

function nextBirthdayDate(birthdayStr) {
  if (!birthdayStr) return '';
  const b = new Date(birthdayStr);
  if (isNaN(b.getTime())) return '';
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  let next = new Date(today.getFullYear(), b.getMonth(), b.getDate());
  if (next < today) next = new Date(today.getFullYear() + 1, b.getMonth(), b.getDate());
  return next.toISOString().split('T')[0];
}

const c = $input.first().json;
const priority = c.priority || 'Medium';
const busy = c.busy_level || 'Moderate';
const category = c.relationship_category || 'Acquaintance';

let cadenceDays = BASE_DAYS[priority] ?? 60;
cadenceDays = cadenceDays * (BUSY_MULTIPLIER[busy] ?? 1);
if (category === 'New Contact') cadenceDays = Math.min(cadenceDays, 14);
cadenceDays = roundToWeek(cadenceDays);

const nextFollowUpDate = addDays(c.last_contacted_date, cadenceDays);
const approach = APPROACH_NOTES[category] || APPROACH_NOTES['Acquaintance'];

return [{
  json: {
    ...c,
    cadence_days: cadenceDays,
    next_follow_up_date: nextFollowUpDate,
    relationship_plan_note: `Suggested cadence: every ${cadenceDays} days. ${approach}`,
    next_birthday_date: nextBirthdayDate(c.birthday),
    followup_event_created: 'true'
  }
}];
